```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"

	"github.com/hashicorp/go-avroparse/schema"
)

// StructToAvro converts a given Go struct into an Avro schema.
func StructToAvro(file string) error {
	fileData, err := ioutil.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading file: %w", err)
	}

	// Parse the Go source code
	tree, err := parser.ParseFile(token.NewFileSet(), "", string(fileData), 0)
	if err != nil {
		return fmt.Errorf("parsing file: %w", err)
	}
	ast.Walk(func(node ast.Node) error {
		if n, ok := node.(*ast.Field); ok {
			name := n.Name
			typeName := n.Type.String()
			fmt.Printf("Field Name: %s\nType: %s\n", name, typeName)
		} else if n, ok := node.(*ast.StructBody); ok {
			structName := "StructName" // Replace with your actual struct name
			fmt.Printf("Struct Name: %s\n", structName)
			var avroSchema schema.Schema
			for _, field := range n.Fields.List {
				fieldName := field.Names[0].Name
				fieldType := field.Type
				fmt.Printf("Field Name: %s, Type: %s\n", fieldName, fieldType)
				avroSchema.AddField(fieldName, schema.Field{Name: fieldName, Type: schema.Type(typeName)})
			}
			schemaPath := fmt.Sprintf("%s.avsc", structName)
			err = json.MarshalIndent(avroSchema, "", "\t")
			if err != nil {
				return fmt.Errorf("marshaling schema: %w", err)
			}
			err = ioutil.WriteFile(schemaPath, []byte(avroSchema.String()), 0644)
			if err != nil {
				return fmt.Errorf("writing schema to file: %w", err)
			}
			fmt.Println(fmt.Sprintf("Generated Avro schema for %s.avsc", structName))
			return nil
		}
		return nil
	})

	return nil
}

func main() {
	if len(os.Args) < 3 {
		log.Fatalf("Usage: %s FILE STRUCT_NAME", os.Args[0])
	}

	file := os.Args[1]
	structName := os.Args[2]

	if err := StructToAvro(file); err != nil {
		log.Fatalf("Error parsing or generating AVRO schema: %v", err)
	}
}
```

